<template>
  <section class="access-panel" role="dialog" aria-modal="true" :aria-label="mode==='scanner'?'Escáner QR':'Asistencia facial'">
    <header class="access-head"><div><small>CONTROL DE ACCESO · SEDE {{ sedeId }}</small><h2>{{ mode==='scanner'?'ESCÁNER QR':'ASISTENCIA FACIAL' }}</h2><p>{{ mode==='scanner'?'Escanea el pase digital del socio.':'Cámara de reconocimiento: pendiente de integración biométrica.' }}</p></div><button type="button" @click="$emit('close')">×</button></header>
    <div class="access-body">
      <div class="camera-frame"><video ref="video" autoplay playsinline muted></video><div v-if="mode==='scanner'" class="scan-box"></div></div>
      <p v-if="error" class="access-error" role="alert">{{ error }}</p>
      <template v-if="mode==='scanner'"><p class="access-help">{{ scanning?'Apunta la cámara hacia el QR del cliente.':'Si el navegador no puede detectar QR, escribe o pega el código del pase.' }}</p><form class="access-form" @submit.prevent="registrar"><input v-model.trim="codigo" maxlength="64" minlength="64" placeholder="Código QR (64 caracteres)" autocomplete="off" aria-label="Código del QR" /><button :disabled="saving || codigo.length!==64" type="submit">{{ saving?'Registrando...':'Registrar entrada' }}</button></form></template>
      <p v-else class="access-help">La cámara funciona, pero todavía no existe un motor de identificación facial ni consentimiento y enrolamiento biométrico. Para registrar entradas verificadas utiliza Escáner QR; no se registrarán rostros sin identificar.</p>
      <div v-if="resultado" class="access-result" :class="resultado.duplicado?'dup':resultado.permitido?'ok':'warn"><strong>{{ resultado.mensaje }}</strong><p>{{ resultado.nombre }} · {{ resultado.estatus }}</p><p>Inscrito en sede {{ resultado.sede_registro }} · Escaneado en sede {{ resultado.sede_escaneo }}</p><p v-if="resultado.aviso">{{ resultado.aviso }}</p></div>
    </div>
    <footer><button type="button" @click="$emit('close')">Cerrar</button></footer>
  </section>
</template>
<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';
const props=defineProps<{mode:'facial'|'scanner';sedeId:number}>();
const emit=defineEmits<{(e:'close'):void;(e:'registered'):void}>();
const video=ref<HTMLVideoElement|null>(null),codigo=ref(''),error=ref(''),saving=ref(false),scanning=ref(false),resultado=ref<Record<string,any>|null>(null);
let stream:MediaStream|null=null,frame=0,detector:any=null,busy=false,alive=true,lastQR='';
const API=String(import.meta.env.VITE_API_URL||'').replace(/\/+$/,'').replace(/\/api$/i,'');
const getToken=()=>{for(const storage of [sessionStorage,localStorage]){for(const key of ['token','auth_token','access_token','gym_token','GYM_ACCOUNT_token','gymAccountToken']){const t=storage.getItem(key);if(t)return t.replace(/^Bearer\s+/i,'');}for(const key of ['auth','user','session','gymAccount','gym_account'])try{const o=JSON.parse(storage.getItem(key)||'null');const t=o?.token||o?.access_token||o?.accessToken;if(t)return String(t).replace(/^Bearer\s+/i,'');}catch{}}return '';};
const registrar=async()=>{if(busy||codigo.value.length!==64)return;busy=true;saving.value=true;error.value='';resultado.value=null;try{const token=getToken();if(!token)throw new Error('Inicia sesión para registrar asistencias.');const response=await fetch(`${API}/api/gym/control-acceso/registrar`,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({sede_id:props.sedeId,codigo_qr:codigo.value})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||`Error HTTP ${response.status}`);resultado.value=data;if(data.registrado)emit('registered');codigo.value='';}catch(e){error.value=e instanceof Error?e.message:'No fue posible registrar la asistencia.';}finally{saving.value=false;busy=false;}};
const scan=async()=>{if(!alive||!detector||!video.value)return;try{if(video.value.readyState>=2&&!saving.value&&!busy){const found=await detector.detect(video.value);const raw=String(found?.[0]?.rawValue||'').trim();if(raw.length===64&&raw!==lastQR){lastQR=raw;codigo.value=raw;await registrar();}}}catch{}if(alive)frame=window.setTimeout(scan,550);};
onMounted(async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:props.mode==='scanner'?'environment':'user'},audio:false});if(!alive){stream.getTracks().forEach(t=>t.stop());return;}if(video.value){video.value.srcObject=stream;await video.value.play().catch(()=>{});}if(props.mode==='scanner'){const D=(window as any).BarcodeDetector;if(D){detector=new D({formats:['qr_code']});scanning.value=true;void scan();}else error.value='Este navegador no admite lectura QR automática. Puedes pegar el código manualmente.';}}catch{error.value='No se pudo abrir la cámara. Verifica permisos y conexión HTTPS. En QR puedes introducir el código manualmente.';}});
onUnmounted(()=>{alive=false;window.clearTimeout(frame);stream?.getTracks().forEach(t=>t.stop());});
</script>
<style scoped>
.access-panel{width:min(94vw,720px);max-height:92vh;overflow:auto;background:#1b1b2b;border:1px solid #ffffff20;border-radius:20px;color:#f5f5f7;box-shadow:0 28px 70px #000a;font-family:Inter,sans-serif}.access-head{padding:23px 25px;display:flex;justify-content:space-between;gap:14px;border-bottom:1px solid #ffffff18}.access-head small{font-size:10px;font-weight:800;letter-spacing:1.6px;color:#ffad73}.access-head h2{font-size:24px;margin:5px 0;font-weight:800}.access-head p,.access-help{color:#a5a5bc;font-size:13px;margin:5px 0}.access-head button{height:36px;width:36px;background:#ffffff12;border:1px solid #ffffff22;border-radius:10px;color:#ddd;cursor:pointer;font-size:24px}.access-body{padding:22px 25px}.camera-frame{position:relative;margin:auto;max-width:560px;aspect-ratio:16/9;background:#0b0c11;border:1px solid #ffffff24;border-radius:15px;overflow:hidden}.camera-frame video{width:100%;height:100%;object-fit:cover}.scan-box{position:absolute;inset:14% 34%;border:3px solid #ffad73;border-radius:16px;pointer-events:none}.access-help{margin:16px 0}.access-form{display:flex;gap:9px;flex-wrap:wrap}.access-form input{flex:1;min-width:190px;padding:13px;border:1px solid #ffffff24;border-radius:10px;background:#101017;color:white}.access-form button{border:0;background:#e64e7d;border-radius:10px;color:white;padding:10px 20px;font-weight:700;cursor:pointer}.access-form button:disabled{opacity:.5;cursor:not-allowed}.access-error{padding:12px;color:#ff8888;background:#ff555514;border-radius:9px}.access-result{padding:14px;border-radius:12px;margin-top:16px;background:#20c99712;border:1px solid #20c99745}.access-result.warn{background:#ffaa0015;border-color:#ffaa0055}.access-result.dup{background:#7981aa15;border-color:#7981aa55}.access-result p{font-size:12px;margin:7px 0}.access-panel footer{padding:12px 25px 20px;display:flex;justify-content:flex-end}.access-panel footer button{background:#ffffff11;color:#ddd;border:1px solid #ffffff25;padding:10px 22px;border-radius:9px;cursor:pointer}
</style>
